function destination(){try{const next=new URL(new URLSearchParams(location.search).get('next')||'/',location.origin);return next.origin===location.origin&&['/','/index.html','/projects.html'].includes(next.pathname)?next.pathname+next.search:'/';}catch{return '/';}}
const $=id=>document.getElementById(id);let setup=false;
async function init(){try{const response=await fetch('/api/auth/status');const state=await response.json();if(!response.ok)throw Error(state.error);if(state.authenticated){location.replace(destination());return;}setup=!state.configured;$('heading').textContent=setup?'Crea tu acceso':'Bienvenido de nuevo';$('intro').textContent=setup?'Elige el usuario y la contraseña para tu visor.':'Introduce tu usuario y contraseña para continuar.';$('submit').textContent=setup?'Crear cuenta y entrar':'Entrar';$('confirm-group').hidden=!setup;$('confirm').required=setup;$('password-help').hidden=!setup;$('password').minLength=setup?12:1;$('password').autocomplete=setup?'new-password':'current-password';$('auth-form').hidden=false;}catch(e){$('intro').textContent=e.message||'No se pudo conectar. Vuelve a abrir el visor.';}}
$('auth-form').addEventListener('submit',async e=>{e.preventDefault();$('message').textContent='';if(setup&&$('password').value!==$('confirm').value){$('message').textContent='Las contraseñas no coinciden.';return;}$('submit').disabled=true;try{const response=await fetch(setup?'/api/auth/setup':'/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('username').value,password:$('password').value})});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudo iniciar sesión.');$('password').value='';$('confirm').value='';location.replace(destination());}catch(e){$('message').textContent=e.message;}finally{$('submit').disabled=false;}});init();
